    /// Keep stress and similar marks in the output (on by default).
    pub fn marks(mut self, on: bool) -> Self {
        self.options.marks = on;
        self
    }

    /// A noun form.
    pub fn noun_scored(&self, word: &str, article: Article, number: Number) -> Scored<String> {
        let cell: Option<u32> = match (article, number,) {
            (Article::Indefinite, Number::Singular,) => Some(0),
            (Article::Indefinite, Number::Plural,) => Some(1),
            (Article::Definite, Number::Singular,) => Some(2),
            (Article::Definite, Number::Plural,) => Some(3),
            (Article::Proximal, Number::Singular,) => Some(4),
            (Article::Proximal, Number::Plural,) => Some(5),
            (Article::Distal, Number::Singular,) => Some(6),
            (Article::Distal, Number::Plural,) => Some(7),
        };
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(0, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// A noun form. The best candidate; the word itself if nothing is known.
    pub fn noun(&self, word: &str, article: Article, number: Number) -> String {
        best(self.noun_scored(word, article, number), word)
    }

